// ─────────────────────────────────────────────────────────────────────────────
// Phase 4B-1R.7 — API bearer-token authentication (C3)
//
// Credentials are supplied to the server process out of band (environment),
// by the launcher. They are never sent to, generated by, or readable from
// frontend JavaScript. Origin/CORS are never consulted as authentication.
//
// Lifecycle:
//   - createAuthenticator(env) is a pure function of its input. It reads the
//     two variables once, keeps only SHA-256 digests, and returns an immutable
//     object. No globals, no I/O.
//   - getAuthenticator() builds one process-wide instance lazily on the first
//     request (never at import time, so `next build` cannot fail or capture
//     credentials) and caches it on globalThis for the life of the process.
//   - Rotation: credentials are read exactly once per process. Rotating them
//     requires restarting the server. A misconfigured/unset state is cached
//     too and stays fail-closed until restart.
//   - This does NOT protect against a same-user process that can read the
//     server environment, .env.local, or process memory.
// ─────────────────────────────────────────────────────────────────────────────

import { createHash, timingSafeEqual } from "node:crypto";

export type AuthScope = "task" | "approve";

export const TASK_TOKEN_ENV = "DASK_API_TASK_TOKEN";
export const APPROVE_TOKEN_ENV = "DASK_API_APPROVE_TOKEN";

// 32 random bytes in base64url is 43 chars. Only the base64url alphabet is
// accepted so a malformed value can never silently become a weak credential.
const MIN_TOKEN_LENGTH = 43;
const MAX_TOKEN_LENGTH = 256;
const TOKEN_PATTERN = /^[A-Za-z0-9_-]+$/;
const MAX_PRESENTED_LENGTH = 512;
const ALLOWED_HOSTNAMES = new Set(["localhost", "127.0.0.1", "[::1]"]);

type Env = Readonly<Record<string, string | undefined>>;

export type AuthDecision =
  | { ok: true; scope: AuthScope }
  | { ok: false; status: 401 | 403 | 503; error: string };

export interface Authenticator {
  readonly configured: boolean;
  authenticate(req: Request, required: AuthScope): AuthDecision;
}

function digest(value: string): Buffer {
  return createHash("sha256").update(value, "utf8").digest();
}

function validTokenOrNull(raw: string | undefined): string | null {
  if (typeof raw !== "string") return null;
  if (raw.length < MIN_TOKEN_LENGTH || raw.length > MAX_TOKEN_LENGTH) return null;
  return TOKEN_PATTERN.test(raw) ? raw : null;
}

function hostnameOf(req: Request): string | null {
  const raw = req.headers.get("host");
  let hostWithPort: string;
  if (raw !== null) {
    hostWithPort = raw;
  } else {
    try {
      hostWithPort = new URL(req.url).host;
    } catch {
      return null;
    }
  }
  const lower = hostWithPort.toLowerCase();
  if (lower.startsWith("[")) {
    const end = lower.indexOf("]");
    return end === -1 ? null : lower.slice(0, end + 1);
  }
  const colon = lower.lastIndexOf(":");
  return colon === -1 ? lower : lower.slice(0, colon);
}

function presentedToken(req: Request): string | null {
  const header = req.headers.get("authorization");
  if (header === null) return null;
  const match = /^Bearer ([^\s]+)$/i.exec(header);
  if (!match) return null;
  const token = match[1]!;
  return token.length <= MAX_PRESENTED_LENGTH ? token : null;
}

export function createAuthenticator(env: Env): Authenticator {
  const taskToken = validTokenOrNull(env[TASK_TOKEN_ENV]);
  const approveToken = validTokenOrNull(env[APPROVE_TOKEN_ENV]);

  // Both must be present, valid, and different. Otherwise nothing authenticates.
  const configured =
    taskToken !== null && approveToken !== null && taskToken !== approveToken;

  const taskDigest = configured ? digest(taskToken!) : null;
  const approveDigest = configured ? digest(approveToken!) : null;

  return Object.freeze({
    configured,
    authenticate(req: Request, required: AuthScope): AuthDecision {
      if (!configured || taskDigest === null || approveDigest === null) {
        return { ok: false, status: 503, error: "API authentication is not configured" };
      }

      const hostname = hostnameOf(req);
      if (hostname === null || !ALLOWED_HOSTNAMES.has(hostname)) {
        return { ok: false, status: 403, error: "Forbidden" };
      }

      const token = presentedToken(req);
      if (token === null) {
        return { ok: false, status: 401, error: "Unauthorized" };
      }

      // Constant-time over digests, and always evaluate both scopes so the
      // timing does not reveal which credential a caller guessed closest to.
      const candidate = digest(token);
      const isTask = timingSafeEqual(candidate, taskDigest);
      const isApprove = timingSafeEqual(candidate, approveDigest);

      if (!isTask && !isApprove) {
        return { ok: false, status: 401, error: "Unauthorized" };
      }
      const held: AuthScope = isTask ? "task" : "approve";
      if (held !== required) {
        return { ok: false, status: 403, error: "Forbidden" };
      }
      return { ok: true, scope: held };
    },
  });
}

const CACHE_KEY = Symbol.for("dask.apiAuth.authenticator.v1");

export function getAuthenticator(): Authenticator {
  const g = globalThis as unknown as Record<symbol, Authenticator | undefined>;
  let cached = g[CACHE_KEY];
  if (cached === undefined) {
    cached = createAuthenticator(process.env);
    g[CACHE_KEY] = cached;
  }
  return cached;
}

/**
 * Route guard. Call as the first statement of every exported handler, before
 * reading the body, params, or query. Returns a Response to send, or null when
 * the caller is authenticated for `scope`.
 */
export function requireAuth(req: Request, scope: AuthScope): Response | null {
  const decision = getAuthenticator().authenticate(req, scope);
  if (decision.ok) return null;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": "no-store",
  };
  if (decision.status === 401) headers["WWW-Authenticate"] = "Bearer";
  return new Response(JSON.stringify({ error: decision.error }), {
    status: decision.status,
    headers,
  });
}
